<script lang="ts">
  import type { Tool } from "../tools";
  let { language, commitCutTime, cutEndInput=$bindable(), cutStartInput=$bindable(), cutTimeEditing=$bindable(), editableTime, handleCutTimeKey, hoverTimeline, markCutAtPlayhead, duration, playerTime, rangeTimelineTool, seekTimeline, selected, setScreenshotTime, startToolTimelineDrag, timelineBounds, timelineHandleKey, timelineHover=$bindable(), timelineTime, toolNumber, toolboxCurrent, toolboxFilmstripLoading, toolboxFilmstripUrl, toolboxTimeline=$bindable() }:{ language:"tr"|"en"; commitCutTime:(key:"start"|"end")=>void; cutEndInput:string; cutStartInput:string; cutTimeEditing:"start"|"end"|null; editableTime:(value:number)=>string; handleCutTimeKey:(event:KeyboardEvent,key:"start"|"end")=>void; hoverTimeline:(event:PointerEvent)=>void; markCutAtPlayhead:(key:"start"|"end")=>void; duration:number; playerTime:(value:number)=>string; rangeTimelineTool:()=>boolean; seekTimeline:(event:MouseEvent)=>void; selected:Tool|null; setScreenshotTime:(value:string)=>void; startToolTimelineDrag:(event:PointerEvent,mode:"start"|"end"|"point"|"range")=>void; timelineBounds:()=>{start:number;end:number}; timelineHandleKey:(event:KeyboardEvent,mode:"start"|"end"|"point")=>void; timelineHover:number|null; timelineTime:(value:number)=>string; toolNumber:(key:string)=>number; toolboxCurrent:number; toolboxFilmstripLoading:boolean; toolboxFilmstripUrl:string; toolboxTimeline:HTMLElement|null }=$props();
</script>

<div class="tool-timeline panel">
  <header><div><h3>{language==="tr"?"ZAMAN ÇİZELGESİ":"TIMELINE"}</h3><p>{selected?.id === "screenshot" ? (language==="tr"?"kare zamanını seç":"choose frame time") : (language==="tr"?"çıktı aralığını seç":"choose export range")}</p></div>{#if selected?.id==="cut"}<span class="timeline-current mono"><i>▶</i> {language==="tr"?"KONUM":"PLAYHEAD"} {editableTime(toolboxCurrent)}</span>{/if}<b class="mono">{selected?.id === "screenshot" ? playerTime(timelineBounds().start) : `${timelineTime(timelineBounds().start)} — ${timelineTime(timelineBounds().end)}`}</b></header>
  {#if rangeTimelineTool()}<div class="cut-timecodes"><div class="cut-timecode"><span>{language==="tr"?"BAŞLANGIÇ":"START"} <i>H:M:S</i></span><input aria-label={language==="tr"?"Başlangıç zamanı":"Start time"} class="mono" bind:value={cutStartInput} onfocus={()=>cutTimeEditing="start"} onblur={()=>commitCutTime("start")} onkeydown={(event)=>handleCutTimeKey(event,"start")} placeholder="0:05:14"><button onclick={()=>markCutAtPlayhead("start")} title={language==="tr"?"Geçerli oynatma zamanını başlangıç yap (I)":"Set IN to current playhead time (I)"}><b>IN</b><kbd>I</kbd></button></div><div class="cut-timecode"><span>{language==="tr"?"BİTİŞ":"END"} <i>H:M:S</i></span><input aria-label={language==="tr"?"Bitiş zamanı":"End time"} class="mono" bind:value={cutEndInput} onfocus={()=>cutTimeEditing="end"} onblur={()=>commitCutTime("end")} onkeydown={(event)=>handleCutTimeKey(event,"end")} placeholder="0:05:46"><button onclick={()=>markCutAtPlayhead("end")} title={language==="tr"?"Geçerli oynatma zamanını bitiş yap (O)":"Set OUT to current playhead time (O)"}><b>OUT</b><kbd>O</kbd></button></div><small class="cut-seek-help">{language==="tr"?"PLAYER ÇUBUĞU: tekerlek ±1 sn · Ctrl+tekerlek ±5 sn · Shift+tık tam saniye":"PLAYER BAR: wheel ±1 sec · Ctrl+wheel ±5 sec · Shift+click whole second"}</small></div>{/if}
  {#if selected?.id==="screenshot"}<div class="screenshot-timecode"><label for="screenshot-time">{language==="tr"?"Kare zamanı":"Frame timestamp"}</label><input id="screenshot-time" class="mono" aria-label={language==="tr"?"Kare zamanı":"Frame timestamp"} value={editableTime(toolNumber("timestamp"))} placeholder="0:00:05.250" onblur={(event)=>{setScreenshotTime(event.currentTarget.value);event.currentTarget.value=editableTime(toolNumber("timestamp"))}} onkeydown={(event)=>{if(event.key==="Enter"){event.preventDefault();event.currentTarget.blur()}if(event.key==="Escape"){event.currentTarget.value=editableTime(toolNumber("timestamp"));event.currentTarget.blur()}}}/><small>{language==="tr"?"Saniye, M:S veya H:M:S · örnek: 5.250":"Seconds, M:S or H:M:S · example: 5.250"}</small></div>{/if}
  <div class="tool-wave" bind:this={toolboxTimeline} onclick={seekTimeline} onpointermove={hoverTimeline} onpointerleave={()=>timelineHover=null} role="presentation">
    {#if toolboxFilmstripUrl}<img class="filmstrip" src={toolboxFilmstripUrl} alt="Video filmstrip" draggable="false">{:else}<span class="wave-loading">{toolboxFilmstripLoading ? (language==="tr"?"video kareleri hazırlanıyor…":"building video frames…") : "—"}</span>{/if}
    {#if selected?.id === "screenshot"}
      <i class="timeline-point" role="slider" tabindex="0" aria-label={language==="tr"?"Zaman":"Timestamp"} aria-valuemin="0" aria-valuemax={duration} aria-valuenow={timelineBounds().start} style:left={`${timelineBounds().start/duration*100}%`} onkeydown={(event)=>timelineHandleKey(event,"point")} onpointerdown={(event)=>startToolTimelineDrag(event,"point")}><b></b></i>
    {:else}
      <div class="timeline-selection" style:left={`${timelineBounds().start/duration*100}%`} style:width={`${Math.max(0,timelineBounds().end-timelineBounds().start)/duration*100}%`} onpointerdown={(event)=>startToolTimelineDrag(event,"range")} role="presentation">
        <i class="timeline-edge left" role="slider" tabindex="0" aria-label={language==="tr"?"Başlangıç":"Start"} aria-valuemin="0" aria-valuemax={timelineBounds().end} aria-valuenow={timelineBounds().start} onkeydown={(event)=>timelineHandleKey(event,"start")} onpointerdown={(event)=>startToolTimelineDrag(event,"start")}></i><i class="timeline-edge right" role="slider" tabindex="0" aria-label={language==="tr"?"Bitiş":"End"} aria-valuemin={timelineBounds().start} aria-valuemax={duration} aria-valuenow={timelineBounds().end} onkeydown={(event)=>timelineHandleKey(event,"end")} onpointerdown={(event)=>startToolTimelineDrag(event,"end")}></i>
      </div>
    {/if}
    {#if timelineHover!==null}<i class="timeline-hover" class:right={timelineHover>85} style:left={`${timelineHover}%`}><b>{playerTime(duration*timelineHover/100)}</b></i>{/if}
    <em class="timeline-playhead" style:left={`${toolboxCurrent/duration*100}%`}></em>
  </div>
  <div class="tool-ruler mono"><span>{timelineTime(0)}</span><span>{timelineTime(duration/4)}</span><span>{timelineTime(duration/2)}</span><span>{timelineTime(duration*3/4)}</span><span>{timelineTime(duration)}</span></div>
</div>
